#include <bits/stdc++.h>
using namespace std;
void dfs(int i, vector<int>& temp , vector<int>& adj , vector<int>& vis, vector<int>& a){
    if(vis[i]==1){
        return;
    }
    vis[i]= 1;
    temp.push_back(a[i]);
    dfs(adj[i], temp, adj , vis , a);
    return;
}
void solve(){
    
    int n,c;
    
    cin >> n>> c;
    
    vector<int> p(n+1);
    vector<int> a(n+1);
    for(int i = 1;i<=n;i++){
        cin >>p[i];
    }
    
    for(int i=1;i<=n;i++){
        cin >> a[i];
    }
    vector<int> vis(n+1 , 0);
    vector<vector<int>> check;
    int ans = 0;
    vector<int> adj(n+1);
    for(int i=1;i<=n;i++){
        adj[i] = (p[i]);
    }
    
    // for (int i = 1; i <= n; i++){
    //     cout << i << " -> " << adj[i]<< " "; 
    //     cout << "\n";
    // }
    for(int i=1;i<=n;i++){
        vector<int> temp;
        if(vis[i]==0){
            dfs(i, temp , adj , vis , a);
        }
        check.push_back(temp);
    }
    int g = 0;
    for(auto it:check){
        int ans = 0;
        sort(it.begin() , it.end(), greater<int>());
        int sz = it.size();
        if (sz == 0) continue;
        vector<int> pre(sz, it[0]);
        for (int i = 1; i < sz; i++) pre[i] = pre[i - 1] + it[i];
        ans = max(0, pre[sz - 1] - (c * (sz - 1)));
        for (int i = 0; i < sz - 1; i++){
            ans = max(ans , pre[i] - c * (i + 1)); 
        }
        // cout << ans << endl;
        g+=ans;
    }
    cout << g;
    
    
    
    
    
    
}

int main() {
	// your code goes here
	
	int t;
	cin >> t;
	
	while(t--){
	    solve();
	    cout << endl;
	}

}
